def load_not_done() -> list[dict]:
    tasks = []
    with NOT_DONE_FILE.open(encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            tasks.append(
                {
                    "id": obj["id"],
                    "title": obj["title"],
                    "priority": obj["priority"],
                    "due": obj["due"],
                    "done": obj["done"],
                }
            )
    return tasks

